// Lucca: blog cards and the post template in the live Webflow markup (src/webflow/blog-*.html, generated by
// client-docs/webflow/tools/port-lucca.mjs from the live /blog, /blog-category/technology and a post page).
import type { CollectionEntry } from "astro:content";
import { getImage } from "astro:assets";
import { postHref } from "./data/blog";
import { getAllBlogCategories } from "./data/blogCategories";
import indexTemplate from "../webflow/blog-index.html?raw";
import postTemplate from "../webflow/blog-post.html?raw";
import cardTemplate from "../webflow/blog-card.html?raw";
import catCardTemplate from "../webflow/blog-card-cat.html?raw";
import postMeta from "../webflow/blog-post.json";

export { indexTemplate, postTemplate };
export const postPageId: string = postMeta.pageId;
/** The live /blog list's collection-list limit: the 100 newest posts (older ones are only reachable by URL). */
export const BLOG_LIMIT = 100;

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

/** Webflow's "MMMM D, YYYY" for Created On, in the site's time zone (Asia/Dhaka). */
export const wfDate = (post: CollectionEntry<"blog">) => {
  const d = post.data.webflowCreatedOn ? new Date(post.data.webflowCreatedOn) : post.data.pubDate;
  return d.toLocaleDateString("en-US", { timeZone: post.data.webflowCreatedOn ? "Asia/Dhaka" : "UTC", year: "numeric", month: "long", day: "numeric" });
};

/** Thumbnail URL (original width, as the live CDN serves it), or "" when the post has none. */
export async function thumbUrl(post: CollectionEntry<"blog">) {
  const t = post.data.postThumbnail;
  return t ? (await getImage({ src: t, width: t.width })).src : "";
}

const EMPTY_IMG = "/images/wf/placeholder.60f9b1840c.svg";
/** Fills an <img src="{{IMG}}"…{{SRCSET}} class="…"> slot; an empty image gets Webflow's w-dyn-bind-empty (hidden). */
export function fillImg(html: string, src: string, srcset?: string, sizes?: string) {
  if (src) return html.replace("{{IMG}}", src).replace("{{SRCSET}}", srcset && sizes ? ` sizes="${sizes}" srcset="${srcset}"` : "");
  // the slot's own <img> (not the first image of the fragment): from "<img src="{{IMG}}"" to its ">"
  const at = html.indexOf('src="{{IMG}}"');
  const start = html.lastIndexOf("<img", at), end = html.indexOf(">", at);
  const tag = html.slice(start, end + 1).replace("{{IMG}}", EMPTY_IMG).replace("{{SRCSET}}", "").replace(/class="([^"]*)"/, 'class="$1 w-dyn-bind-empty"');
  return html.slice(0, start) + tag + html.slice(end + 1);
}

/** One /blog card, exactly as Webflow renders a Blog Posts item (the category variant when it has one). */
export async function card(post: CollectionEntry<"blog">) {
  const cat = post.data.category[0];
  let html = cat ? catCardTemplate : cardTemplate;
  if (cat) {
    const name = (await getAllBlogCategories()).find((c) => c.id === cat.id)?.data.name ?? cat.id;
    html = html.replace("{{CATHREF}}", `/blog-category/${cat.id}`).replace("{{CAT}}", esc(name));
  }
  html = fillImg(html, await thumbUrl(post));
  return html.split("{{HREF}}").join(postHref(post)).replace("{{TITLE}}", esc(post.data.name)).replace("{{DATE}}", wfDate(post));
}
